#!/bin/sh
# Autogenerated test: runs inside a container built from each compatibility image with betterleaks installed with
# default options (version latest). POSIX sh, because alpine:3.24 ships no bash.
set -eu

# The path is computed from $0 at run time, so shellcheck cannot follow it.
# shellcheck source=/dev/null
. "$(dirname "$0")/checks.sh"

# Computed at run time: the default option installs whatever release the latest-release link names.
latest="$(latest_release)"

# Before betterleaks runs at all, so a file it might write cannot pass as pre-existing.
check "neither the remote user's nor root's home holds a file whose name contains betterleaks" \
  no_betterleaks_files_in_homes

no_betterleaks_variables() {
  no_betterleaks_variables_set="$(env | grep '^BETTERLEAKS_' || true)"
  if [ -n "${no_betterleaks_variables_set}" ]; then
    printf '  set: %s\n' "${no_betterleaks_variables_set}"
    return 1
  fi
}
check "no environment variable whose name starts with BETTERLEAKS_ is set" no_betterleaks_variables

check "command -v betterleaks resolves to /usr/local/bin/betterleaks" betterleaks_resolves_to_usr_local_bin
check "betterleaks version exits 0" betterleaks version
check "git --version exits 0" git --version
check "betterleaks version reports the release the latest-release link points to" \
  betterleaks_reports_version "${latest}"

# A repository with one empty commit holds no secret; betterleaks git exits 0 and reports no finding on it.
scan_of_clean_repository_finds_nothing() {
  scan_repository="$(mktemp -d)"
  git init --quiet "${scan_repository}" || return 1
  git -C "${scan_repository}" -c user.name=test -c user.email=test@example.com \
    commit --quiet --allow-empty --message 'empty' || return 1
  scan_output="$(betterleaks git "${scan_repository}" 2>&1)" || {
    printf '%s\n' "${scan_output}"
    return 1
  }
  printf '%s\n' "${scan_output}" | grep -i 'no leaks found' >/dev/null
}
check "betterleaks git exits 0 and reports no finding on a repository without secrets" \
  scan_of_clean_repository_finds_nothing

# No file under apt's package lists, dnf's cache, or apk's cache, whichever of them the image has.
package_caches_empty() {
  for package_caches_empty_dir in /var/lib/apt/lists /var/cache/libdnf5 /var/cache/apk; do
    if [ ! -d "${package_caches_empty_dir}" ]; then continue; fi
    package_caches_empty_files="$(as_root find "${package_caches_empty_dir}" -type f)" || return 1
    if [ -n "${package_caches_empty_files}" ]; then
      printf '  files remain under %s:\n%s\n' "${package_caches_empty_dir}" "${package_caches_empty_files}"
      return 1
    fi
  done
}
check "apt's package lists, dnf's cache, and apk's cache hold no file" package_caches_empty
check "no temporary directory or staged binary of the install remains" no_install_leftovers

reportResults
